<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'; import AppLayout from '../components/layout/AppLayout.vue'; import ReportNav from '../components/reports/ReportNav.vue'; import SummaryCards from '../components/reports/SummaryCards.vue'; import BarChart from '../components/reports/BarChart.vue'; import LoadingState from '../components/ui/LoadingState.vue'; import BaseButton from '../components/ui/BaseButton.vue'; import { yearlyReport, downloadExport } from '../services/reports'; import { apiErrorMessage } from '../services/api'; import { formatMoney } from '../utils/formatters'; import type { ReportData } from '../types';
const year = ref(new Date().getFullYear()); const report = ref<ReportData | null>(null); const loading = ref(true); const error = ref(''); const months = computed(() => report.value?.months?.map(m => ({ label: new Date(year.value, m.month - 1).toLocaleString(undefined, { month: 'short' }), total: m.total })) ?? []);
async function load(): Promise<void> { loading.value = true; try { report.value = await yearlyReport(year.value); error.value = ''; } catch (e) { error.value = apiErrorMessage(e); } finally { loading.value = false; } } watch(year, load); onMounted(load);
async function exportYear(): Promise<void> { try { await downloadExport('/exports/yearly.xlsx', { year: year.value }, `yearly-${year.value}.xlsx`); } catch (caught) { error.value = apiErrorMessage(caught, 'Unable to export this report.'); } }
</script>
<template><AppLayout><div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-medium text-brand-700">Reports</p><h1 class="mt-1 text-3xl font-semibold">Yearly report</h1></div><ReportNav /></div><section class="card mt-6 flex flex-wrap items-end gap-3"><label><span class="label">Year</span><input v-model.number="year" class="field w-32" type="number" min="2000" max="2100" /></label><BaseButton variant="secondary" @click="exportYear">Export Excel</BaseButton></section><p v-if="error" class="mt-5 rounded-lg bg-red-50 p-3 text-red-700">{{ error }}</p><LoadingState v-if="loading" label="Loading report…" /><template v-else-if="report"><div class="mt-6"><SummaryCards :summary="report.summary" /></div><div class="card mt-4"><p class="text-sm text-slate-500">Average per calendar month</p><p class="mt-1 text-xl font-semibold">{{ formatMoney(report.average_monthly_amount ?? '0') }}</p></div><div class="mt-6 grid gap-6 xl:grid-cols-2"><section class="card"><h2 class="font-semibold">Monthly trend</h2><BarChart class="mt-5" :items="months" /></section><section class="card"><h2 class="font-semibold">Categories</h2><BarChart class="mt-5" :items="report.categories.map(c => ({ label: c.name, total: c.total }))" /></section></div></template></AppLayout></template>
